02-CommonBase.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
interface I { function f() external; function g() external; }
abstract contract A is I { function f() external {} function g() external virtual; }
abstract contract B is I { function g() external {} function f() external virtual; }
contract C is A, B {}

03-Modifier.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract A { modifier f() virtual { _; } }
contract B { modifier f() virtual { _; } }
contract C is A, B {}

04-PublicGetter.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
interface I {}
contract A is I { uint256 public f; }
abstract contract B is I { function f() external virtual returns (uint256); }
abstract contract C is A, B {}
